window.reviewData=[{"id": "tabs-01-forecast", "title": "Next observation", "normal": "tabs-01-forecast", "note": "The alert action now precedes the preview and pass statistics. Its caption explains that it enables automatic ISS and Tiangong push alerts, rather than scheduling this one pass.", "large": "tabs-01-forecast+large", "largeNote": "The action is now directly below the pass time and station, before supporting detail. The first screen still spends considerable space on the location and station name; keep reducing secondary detail without shrinking readable text.", "beforeNote": "The featured pass is clear, but the large card pushes most upcoming passes below the first viewport.", "beforeLargeNote": "The title, location, weather and pass summary consume the first screen before the reminder action appears.", "beforeLarge": "tabs-01-forecast+large"}, {"id": "tabs-02-pass-chart", "title": "Pass chart · with tabs", "normal": "tabs-02-pass-chart", "note": "The native chart retains its system tab rail and controls. Motion guidance now lives below the visualization. The timeline still requires scrolling; a compact next-event summary is the next useful addition.", "beforeNote": "The system tab rail keeps navigation reachable. Keep the path, direction labels and chart controls within the available content width.", "beforeLargeNote": null, "beforeLarge": null}, {"id": "tabs-03-pass-list", "title": "Upcoming pass list", "normal": "tabs-03-pass-list", "note": "Three complete visible-pass rows fit in the standard-text capture. Each includes rise date/time, sunlit duration, direction and peak elevation. The live globe is collapsed behind an explicit disclosure.", "beforeNote": "The globe and explanation dominate the first screen. Compact pass rows would make comparing times and peak elevations faster.", "beforeLargeNote": null, "beforeLarge": null, "large": "tabs-03-pass-list+large", "largeNote": "Pass facts wrap rather than relying on a fixed card height. The first row consumes much of the screen at accessibility2; day grouping and a shorter direction summary would reduce repeated reading."}, {"id": "tabs-04-satellites", "title": "Satellites", "normal": "tabs-04-satellites", "note": "No app layout change in this pass. Station cards and their summaries fit the outer display. On the inner display, consider keeping categories beside the selected station rather than enlarging these cards.", "beforeNote": "Station cards and their summaries fit the outer display. On the inner display, consider keeping categories beside the selected station rather than enlarging these cards.", "beforeLargeNote": null, "beforeLarge": null}, {"id": "tabs-05-planetarium", "title": "Planetarium", "normal": "tabs-05-planetarium", "note": "No app layout change in this pass. The sky scene and preview controls are visible. The fold and camera reserved regions still need testing on the inner display.", "beforeNote": "The sky scene and preview controls are visible. The fold and camera reserved regions still need testing on the inner display.", "beforeLargeNote": null, "beforeLarge": null}, {"id": "07-pass", "title": "Pass chart · motion guidance", "normal": "07-pass", "note": "The full pass path is visible. A compact help panel and “Use fixed chart” appear beneath the chart, with expanded guidance on request.", "beforeNote": "The no-motion orientation guidance covers the center of the chart and part of the pass path. Move help beside or below the visualization.", "beforeLargeNote": null, "beforeLarge": null, "large": "07-pass+large", "largeNote": "Guidance stays outside the chart. Chart controls and the timeline remain below the first viewport at accessibility2; consider a smaller chart and a concise next-event summary."}, {"id": "07-pass-compass-off", "title": "Pass chart · fixed compass", "normal": "07-pass-compass-off", "note": "A fixed chart remains available through the existing compass toggle and the new direct fallback action. Sensor accuracy and pose transitions still need hardware testing.", "large": "07-pass-compass-off+large", "largeNote": "The visualization is readable, but larger chart controls push the event timeline down. Stack event names and times in the timeline and surface the next event earlier.", "beforeNote": "A fixed chart provides a readable fallback when device motion is unavailable. Keep this state accessible in book and tabletop poses.", "beforeLargeNote": "The chart controls stack at larger text sizes. The event timeline moves below the first screen; an adaptive arrangement could keep the next event reachable.", "beforeLarge": "07-pass-compass-off+large"}, {"id": "08-detailed-sky", "title": "Detailed sky canvas", "normal": "08-detailed-sky", "note": "No app layout change in this pass. This records the fixture’s initial camera position in the interactive sky canvas. Gesture behavior and camera reset require a separate interaction check.", "beforeNote": "This records the fixture’s initial camera position in the interactive sky canvas. Gesture behavior and camera reset require a separate interaction check.", "beforeLargeNote": null, "beforeLarge": null}, {"id": "10-settings", "title": "Settings", "normal": "10-settings", "note": "No app layout change in this pass. The observer, alarms and downloaded-file groups remain legible. Verify the same sheet and navigation context through display changes.", "beforeNote": "The observer, alarms and downloaded-file groups remain legible. Verify the same sheet and navigation context through display changes.", "beforeLargeNote": null, "beforeLarge": null}, {"id": "11-location", "title": "Choose location", "normal": "11-location", "note": "No app layout change in this pass. The search field and selected test observer are visible. The keyboard and inner-display sheet detents have not been tested.", "beforeNote": "The search field and selected test observer are visible. The keyboard and inner-display sheet detents have not been tested.", "beforeLargeNote": null, "beforeLarge": null}, {"id": "12-alarms", "title": "Alarms · empty", "normal": "12-alarms", "note": "The empty state now offers “Choose a pass” and hides Edit. In the production app this opens Forecast’s existing upcoming-pass route. The visual fixture supplies that action without exercising navigation.", "beforeNote": "The empty state explains alarms but provides no direct way to choose a pass. Add a clear next action and hide Edit when there are no alarms.", "beforeLargeNote": null, "beforeLarge": null, "large": "12-alarms+large", "largeNote": "The shorter message and larger touch target provide a clear next step. Verify the route with an actual location selected and with no location available."}, {"id": "13-pass-alarm", "title": "Set a pass reminder", "normal": "13-pass-alarm", "note": "Creation now says “Set reminder.” Event names and exact times occupy separate lines; lead-time presets replace the default wheel controls. Confirmation stays in a bottom safe-area inset.", "large": "13-pass-alarm+large", "largeNote": "The event labels and times wrap without truncation, and “Set reminder” remains visible while the form scrolls. Lower events, lead time and the exact alert summary require scrolling. A pinned selected-event summary would make confirmation safer.", "beforeNote": "The screen says “View alarm” while offering “Schedule alarm.” Use labels that communicate creating versus editing a reminder.", "beforeLargeNote": "Event labels and exact times truncate with larger text. Stack the name and time, simplify lead-time controls, and keep the scheduling action reachable.", "beforeLarge": "13-pass-alarm+large"}, {"id": "01-welcome", "title": "Onboarding · welcome", "normal": "01-welcome", "note": "No app layout change in this pass. Keep the introduction brief and lead quickly to choosing a location and the first useful observation. Fold continuity remains untested.", "beforeNote": "Keep the introduction brief and lead quickly to choosing a location and the first useful observation. Fold continuity remains untested.", "beforeLargeNote": null, "beforeLarge": null}, {"id": "02-predictions-intro", "title": "Onboarding · pass introduction", "normal": "02-predictions-intro", "note": "No app layout change in this pass. Teach the pass path with enough context to interpret the directions. Preserve the current onboarding page through open/close.", "beforeNote": "Teach the pass path with enough context to interpret the directions. Preserve the current onboarding page through open/close.", "beforeLargeNote": null, "beforeLarge": null}];
